--- Criação da DB
CREATE DATABASE clinica_veterinaria;

--- Conexão ao banco
\c clinica_veterinaria

--- Definição de Enum
CREATE TYPE "Status_Consulta" AS ENUM (
  'MARCADA',
  'FINALIZADA',
  'CANCELADA'
);

--- Definição das tabelas
CREATE TABLE "Cliente" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nome" varchar(255),
  "cpf" varchar(14) UNIQUE
);

CREATE TABLE "Paciente" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nome" varchar(255) NOT NULL,
  "especie" varchar(255),
  "raca" varchar(255),
  "cliente_id" int NOT NULL
);

CREATE TABLE "Consulta" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "data_marcada" timestamp NOT NULL,
  "status" "Status_Consulta" NOT NULL DEFAULT 'MARCADA',
  "vet_id" int NOT NULL,
  "paciente_id" int NOT NULL
);

CREATE TABLE "Veterinario" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nome" varchar(255) NOT NULL,
  "cpf" varchar(14) UNIQUE,
  "crmv" varchar(15) UNIQUE,
  "especialidade" varchar(255)
);

CREATE TABLE "Procedimento" (
  "id" INT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nome" varchar(255) UNIQUE NOT NULL,
  "descricao" text,
  "valor_base" decimal(10,2) NOT NULL
);

CREATE TABLE "Procedimento_Consulta" (
  "consulta_id" int NOT NULL,
  "procedimento_id" int NOT NULL,
  "valor_cobrado" decimal(10,2) NOT NULL,
  "observacoes" text
);

--- Criar index em Procedimento_Consulta
--- Consultas devem utilizar o multiindex (consulta_id, procedimento_id)
CREATE INDEX ON "Procedimento_Consulta" ("consulta_id", "procedimento_id");

--- Criação das chaves estrangeiras
ALTER TABLE "Paciente" ADD FOREIGN KEY ("cliente_id") REFERENCES "Cliente" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Consulta" ADD FOREIGN KEY ("vet_id") REFERENCES "Veterinario" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Consulta" ADD FOREIGN KEY ("paciente_id") REFERENCES "Paciente" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Procedimento_Consulta" ADD FOREIGN KEY ("consulta_id") REFERENCES "Consulta" ("id") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "Procedimento_Consulta" ADD FOREIGN KEY ("procedimento_id") REFERENCES "Procedimento" ("id") DEFERRABLE INITIALLY IMMEDIATE;
